function screenPregame(){
  const a = army(), f = faction(), units = a.units;
  const row = (k, v) => v ? '<div class="pgr"><span class="pgk">' + k + '</span><span class="pgv">' + v + '</span></div>' : '';
  const sec = (title, body) => body ? '<div class="sec-h"><h2>' + title + '</h2></div><div class="pg">' + body + '</div>' : '';
  // the same ability on several units is one line: "Singular Purpose · Assimilator (280), Norn Emissary ×2"
  const group = list => { const m = new Map(); for(const [u, ab] of list){ const k = ab.name + '|' + ab.text; if(!m.has(k)) m.set(k, { ab, units:[] }); m.get(k).units.push(u); } return [...m.values()]; };
  const abLine = g => linkTo('ability', abilityKey(g.ab), g.ab.name) + ' <span class="from">· ' + esc(unitNames(g.units, g.ab)) + '</span>';
  const rulesOf = units.length ? f.armyRules.filter(r => !inertRule(r.name)).map(r => ({ r, src:f.name + ' army rule' }))
    .concat(detachments().flatMap(d => detRules(d).map(r => ({ r, src:d.name })))) : [];
  const ruleLine = x => linkTo('rule', x.r.name, x.r.name) + ' <span class="from">· ' + esc(x.src) + '</span>';
  const nameLink = u => linkTo('unit', u.id, u.short || u.name);   // without its enhancement: the line says it
  // a unit's short name, or its full one when another unit of the list has that short name too (Big Mek Dakkarig, Big Mek in Mega Armour)
  const ownName = u => u.short && units.some(x => x !== u && (x.short || x.name) === u.short && x.name !== u.name) ? u.name : u.short || u.name;
  const allAbs = units.flatMap(u => u.abilities.filter(ab => !naReason(ab)).map(ab => [u, ab]));
  // Deep Strike (24.09) and Scouts (24.31) work only if every model in the unit has them; u.partialRules names
  // the rules only some models of an attached unit have (Slaughterbound's Scouts 6": its Exalted Eightbound have none)
  const everyModel = (u, test) => unitRules(u).some(test) && !Object.keys(u.partialRules || {}).some(test);
  // rules resolved before Declare Battle Formations (Code Chivalric: end of the Read Mission Objectives step)
  const early = rulesOf.filter(x => /read mission objectives/i.test(x.r.text));

  // your list
  const warlord = units.filter(u => u.warlord);
  const enh = units.flatMap(u => [u.enhancement, u.upgrade].filter(Boolean).map(n => { const d = detachments().find(x => (x.enhancements || []).some(e => e.name === n)), e = d && d.enhancements.find(x => x.name === n);
    return (d ? linkTo('enh', d.id + '|' + n, n) : esc(n)) + (n === u.upgrade ? ' <span class="from">(upgrade)</span>' : '') + (e && e.pts ? ' <span class="from">' + e.pts + ' pts</span>' : '') + ' on ' + (n === u.enhancement && u.enhOn ? linkTo('unit', u.id, u.enhOn) : n === u.upgrade && u.leads ? linkTo('unit', u.id, u.leads) : linkTo('unit', u.id, ownName(u) + unitNo(u))); }));
  const led = units.filter(u => u.leads).flatMap(u => charsOf(u).map((c, i) => (i ? linkTo('unit', u.id, c.name) : nameLink(u)) + (c.support ? ' supports ' : ' leads ') + esc(u.leads) + (u.copies > 1 ? ' <span class="from">×' + u.copies + ' units</span>' : '')));
  let h = sec('Your list',
    row('Warlord', warlord.map(u => u.warlordOn ? linkTo('unit', u.id, u.warlordOn) + ' <span class="from">(' + esc(unitLabel(u)) + ')</span>' : unitLink(u)).join(', ')) +
    row('Enhance&shy;ments', enh.join('<br>')) +
    row('Attached', led.join('<br>')) +
    row('Detach&shy;ments', detachments().map(d => (d.rule ? linkTo('rule', d.rule.name, d.name) : esc(d.name)) + (d.dp ? ' <span class="from">(' + d.dp + ' DP)</span>' : '')).join(', ')) +
    row('Disposi&shy;tions', dispText(a)) +
    // the other selections New Recruit prints under the army name, as printed; one that only names the parts of an army
    // rule ("Code Chivalric: Deed, Quality", each part's table rows) is no pick: that rule is under Army rules
    Object.entries(a.config || {}).filter(([k, v]) => !ruleParts(f, k, v)).map(([k, v]) => row(esc(k), esc(v))).join('') +
    row('Points', esc(a.pointsUsed + ' / ' + a.points + ' · ' + a.battleSize)));
  // the army rules and the detachment rules, folded: each opens to its text (the detachment's row as on the Rules tab)
  const detRows = detachments().flatMap(d => detRules(d).map(r => ruleRow(r.name, metaLine(esc(d.name), r.ph ? esc(shortWhen(r)) : ''),
    (r.note ? '<p class="note it">' + esc(r.note) + '</p>' : '') + textWithTable(r) + usedBy('Applies to', units.filter(u => matches(r.needs, u)))))).join('');
  h += f.armyRules.length || detRows ? '<div class="sec-h"><h2>' + (detRows ? 'Army and detachment rules' : 'Army rules') + '</h2></div><div class="abl">' + armyRuleRows(f) + detRows + '</div>' : '';

  const earlyAbs = group(allAbs.filter(([u, ab]) => /read mission objectives/i.test(ab.text)));
  h += sec('Read Mission Objectives step', row('Rules', early.map(ruleLine).join('<br>')) + row('Abilities', earlyAbs.map(abLine).join('<br>')));

  // declare battle formations: reserves and transports
  const ds = units.filter(u => everyModel(u, r => ruleKey(r) === 'Deep Strike'));
  const dsPts = ds.reduce((t, u) => t + (u.pts || 0) * (u.copies || 1), 0);
  const transports = units.filter(u => hasKw(u, 'Transport')).map(u => { const ab = u.abilities.find(x => /transport capacity/i.test(x.text)); return unitLink(u) + (ab ? ': <span class="from">' + inline(ab.text.replace(/(^|\n)\*([^*\n][^\n]*[^*\n])\*(?=\n|$)/g, '$1$2').replace(/\n(- )?/g, ' ')) + '</span>' : ''); });
  h += sec('Declare battle formations',
    row(linkTo('rule', 'Deep Strike', 'Deep Strike'), ds.map(u => (u.leads ? linkTo('unit', u.id, unitLabel(u)) : unitLink(u)) + ' <span class="from">' + u.pts + ' pts' + (u.copies > 1 ? ' each, ×' + u.copies : '') + '</span>').join('<br>') + (ds.length > 1 ? '<br><span class="from">All of them: ' + dsPts + ' pts</span>' : '')) +
    row('Transports', transports.join('<br>')));

  // deployment and pre-battle abilities
  const scouts = units.filter(u => everyModel(u, r => /^scouts|^infiltrators/i.test(r)));
  const scoutRules = u => unitRules(u).filter(r => /^scouts|^infiltrators/i.test(r));
  const scoutKeys = [...new Set(scouts.flatMap(u => scoutRules(u).map(ruleKey)))].sort((x, y) => (x === 'Scouts' ? 0 : 1) - (y === 'Scouts' ? 0 : 1));
  const pre = group(allAbs.filter(([u, ab]) => PREGAME_RE.test(ab.text) && !/start of the first battle round|read mission objectives/i.test(ab.text)));
  h += sec('Deployment and pre-battle abilities',
    row(scoutKeys.map(k => linkTo('rule', k, k)).join(' and '), scouts.map(u => unitLink(u) + ' <span class="from">' + scoutRules(u).map(r => linkTo('rule', r, r)).join(', ') + '</span>').join('<br>')) +
    row('Abilities', pre.map(abLine).join('<br>')) +
    row('Rules', rulesOf.filter(x => PREGAME_RE.test(x.r.text) && !early.includes(x)).map(ruleLine).join('<br>')));

  // decided at the start of the battle (before the first battle round: Aegis Protocol, Code Chivalric's Deed 1–2, a row of its
  // table), of the first battle round or of every battle round
  const START = /\bstart of the battle\b(?! round)/i;
  const atStart = rulesOf.flatMap(x => { const rows = START.test(x.r.text) ? [] : (x.r.table || []).filter(([, t]) => START.test(t)).map(([l]) => String(l).split(' · ')[0]);
    return START.test(x.r.text) || rows.length ? [linkTo('rule', x.r.name, x.r.name) + ' <span class="from">' + (rows.length ? '(' + esc(rows.join(', ')) + ') ' : '') + '· ' + esc(x.src) + '</span>'] : []; })
    .concat(group(allAbs.filter(([u, ab]) => START.test(ab.text))).map(abLine));
  const first = group(allAbs.filter(([u, ab]) => /start of the first battle round/i.test(ab.text)));
  const round = rulesOf.filter(x => /start of (the|each|every) battle round/i.test(x.r.text)).map(ruleLine)
    .concat(group(allAbs.filter(([u, ab]) => /start of (the|each|every) battle round/i.test(ab.text) && !/start of the first battle round/i.test(ab.text))).map(abLine));
  const firstRules = rulesOf.filter(x => /start of the first battle round/i.test(x.r.text)).map(ruleLine);
  h += sec('Start of the battle and the battle rounds', row('Start of the battle', atStart.join('<br>')) + row('First round', firstRules.concat(first.map(abLine)).join('<br>')) + row('Every round', round.join('<br>')));

  // uses per battle: the resources you spend, ticked off until New game
  // a rule that gives units a "(Once per battle, per unit)" ability (Higher Imperatives) is ticked on those units, not here
  const ruleOnce = r => perBattle(r) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '');
  const onceRules = f.armyRules.filter(r => !inertRule(r.name) && ruleOnce(r)).map(r => ({ r, src:f.name + ' army rule' }))
    .concat(detachments().flatMap(d => detRules(d).filter(ruleOnce).map(r => ({ r, src:d.name }))));
  const tl = (boxes, text) => '<div class="tl">' + boxes + '<span>' + text + '</span></div>';
  const ruleTicks = x => { const r = x.r, pb = perBattle(r, true);
    // "You can only select each of these abilities once per battle" (Kindred Sorcery), "… each combat doctrine once per battle": a box
    // per option, and one more for each use another rule adds (eachOnce)
    const each = eachOnce(r);
    if(each) return '<div class="tl"><span>' + ruleLine(x) + ':</span></div>' + each.map(([o, n]) => tl(ticks('r:' + r.name + ':' + o, n, '', o), esc(o))).join('');
    return tl(ticks('r:' + r.name, pb.n, '', r.name), ruleLine(x)); };
  const onceAbs = group(allAbs.filter(([u, ab]) => perBattle(ab)));
  const abTicks = g => perBattle(g.ab).army ? tl(abilityTicks(g.ab, g.units[0]), abLine(g) + ' <span class="tg once">per army</span>')
    : g.units.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) => tl(ticks(copyKey(g.ab, u, i), perBattle(g.ab).n, '', g.ab.name + (u.copies > 1 ? ', Unit ' + (i + 1) : '')),
        linkTo('ability', abilityKey(g.ab), g.ab.name) + ' · ' + linkTo('unit', u.id, unitLabel(u)) + (u.copies > 1 ? ' <span class="from">· Unit ' + (i + 1) + '</span>' : '')))).join('');
  const onceStrats = allStratagems().filter(s => eligible(s).length && perBattle(s));
  h += sec('Uses per battle',
    row('Rules', onceRules.map(ruleTicks).join('')) +
    row('Abilities', onceAbs.map(abTicks).join('')) +
    row('Strata&shy;gems', onceStrats.map(s => tl(ticks('s:' + s.id, perBattle(s, true).n, '', s.name), linkTo('strat', s.id, s.cp + 'CP ' + s.name))).join('')));
  if(onceRules.length || onceAbs.length || onceStrats.length) h = h.replace(/(<div class="sec-h"><h2>Uses per battle<\/h2>)/, '$1<button class="textbtn" data-newgame>New game</button>');
  return h + '<p class="note">Gathered from this list’s datasheets and rules; each line opens the full text.</p>' + (a.imported ? importedFoot(a) : '');
}

function screenChecklist(){
  const a = army(), f = faction(), units = a.units;
  const entry0 = k => (D.checklist || {})[k] || { x:1 };
  const rules = f.armyRules.map(r => ({ r, src:f.name + ' army rule' })).concat(detachments().flatMap(d => detRules(d).map(r => ({ r, src:d.name }))));
  // the moments the list's listed rules and abilities make a named roll (ckRollMoments), then each entry with them (ckRolled)
  const rm = ckRollMoments(rules.map(x => [x.r, ckStored(entry0('r|' + a.faction + '|' + x.r.name), x.r)]).concat(units.flatMap(u => u.abilities.map(ab => [ab, ckStored(entry0('a|' + ckHash(ab.name + '\n' + ab.text)), ab)])))
    .filter(([x, e]) => e.s || e.stored));
  const named = new Map(rules.map(x => ['r|' + a.faction + '|' + x.r.name, x.r]).concat(units.flatMap(u => u.abilities.map(ab => ['a|' + ckHash(ab.name + '\n' + ab.text), ab]))));
  const entry = k => named.has(k) ? ckRolled(entry0(k), named.get(k), rm) : entry0(k);
  // what another rule of the list gives to units by keyword: "Might of Khorne (Blood Tithe) gives it to BLOOD LEGIONS units"
  const given = name => rules.flatMap(x => (entry('r|' + a.faction + '|' + x.r.name).g || []).filter(g => g.name === name && units.some(u => matches(g.to, u)))
    .map(g => '; ' + esc((g.opt ? g.opt + ' (' + x.r.name + ')' : x.r.name) + ' gives it to ' + kwWords(g.to) + ' units'))).join('');
  const from = s => ' <span class="from">· ' + s + '</span>', naTag = t => t ? ' <span class="tg m">' + esc(t) + '</span>' : '';
  const tl = (boxes, text) => '<div class="tl">' + boxes + '<span>' + text + '</span></div>';
  // several uses as one (phase:your|opp|either; your and opp of one phase: either)
  const ckUnion = us => { const m = {}; for(const u of us) for(const [p, t] of Object.entries(ckMap(u))) m[p] = m[p] && m[p] !== t ? 'either' : t; return Object.entries(m).map(([p, t]) => p + ':' + t).join(','); };
  const items = [];   // { id, kind, e: its entry, line, what, once: its once-per-battle lines [boxes, text], n: its boxes, one per copy (ckTick) }
  // what a triggered rule or ability puts in force from a rule defined elsewhere (CHECKLIST f): "Riled up (War Cry) · Waaagh!", opening
  // that rule, Active now in the phases the trigger's duration covers (When unclear when the duration cannot be read)
  const forced = (fs, src, kind, id) => { for(const x of fs || []) if(rules.some(y => y.r.name === x.r)) items.push({ id:'f:' + id + ':' + x.r, kind, e:x.x ? { x:1 } : { u:x.u },
    what:x.n, line:linkTo('rule', x.r, x.n.charAt(0).toUpperCase() + x.n.slice(1) + ' (' + src + ')') + from(esc(x.r)), once:null }); };
  for(const x of rules){
    const r = x.r, e = ckStored(entry('r|' + a.faction + '|' + r.name), r), na = inertRule(r.name) ? 'no unit in this list it applies to' : '';
    // "You can only select each of these abilities once per battle" (Kindred Sorcery), "… each combat doctrine once per battle"
    // (Combat Doctrines): a limit on its options, not a once-per-battle rule; a box per option, as on the Overview (eachOnce)
    const each = eachOnce(r);
    const pb = !na && !each && !CK_EACH_ONCE.test(r.text || '') && perBattle(r, true) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '') ? perBattle(r, true) : null;
    // which battle rounds, quoted, when its words name some ("at the start of the first, third and fifth battle rounds")
    const rounds = /\bat the start of the ((?:(?:first|second|third|fourth|fifth)(?:, | and | or ))*(?:first|second|third|fourth|fifth)) battle rounds\b/i.exec(String(r.text || '').replace(/\*\*|~~/g, ''));
    const line = linkTo('rule', r.name, r.name) + from(esc(x.src) + given(r.name) + (rounds ? ' (' + esc(rounds[1]) + ' battle rounds)' : '')) + naTag(na), trig = ckListed(e, pb);
    // a rule listed only through options with moments of their own (Code Chivalric's Deeds): the rule, once; its options are in its text
    // (placed at the end moments its options name, Code Chivalric's Deeds: a reminder to check, at each; none: as its own entry says)
    if(!trig && (e.o || []).some(o => o.s && !units.some(u => u.abilities.some(ab => ab.name === o.n)))){ const ends = [...new Set((e.o || []).flatMap(o => o.ends || []))];
      items.push({ id:'r:' + r.name, kind:'rules', e:ends.length ? { ends } : e, line, what:r.name, once:null }); continue; }
    // (what a once-per-battle use puts in force is not listed: its box is)
    if(trig){ items.push({ id:'r:' + r.name, kind:'rules', e, line, what:r.name, once:pb ? [[ticks('r:' + r.name, pb.n, '', r.name), line]] : null }); if(!pb) forced(e.f, r.name, 'rules', 'r:' + r.name); }
    for(const o of e.o || []){
      // its boxes when each option is once per battle (eachOnce: the row of its table, else the option itself), where the rule is chosen
      const row = each && !na && each.find(([n]) => n === (r.table ? o.row : o.n));
      // an option of a rule not listed, or one that is a unit activation (unless it has its own boxes: Assault Doctrine)
      if(!ckOptListed(o, trig) && !(row && trig)) continue;
      if(units.some(u => u.abilities.some(ab => ab.name === o.n))) continue;   // an ability it gives units (Protean Purpose): listed as theirs
      const ol = linkTo('rule', r.name, o.n) + from('option of ' + esc(r.name) + given(o.n)) + naTag(na);
      items.push({ id:'o:' + r.name + ':' + o.n, kind:'rules', e:ckOption(o, e), line:ol, what:o.n, once:row ? [[ticks('r:' + r.name + ':' + row[0], row[1], '', row[0]), ol]] : null });
      forced(o.f, o.n, 'rules', 'o:' + r.name + ':' + o.n);
    }
  }
  // abilities: the same ability on several units is one line, as on the Overview
  const groups = new Map();
  for(const u of units) for(const ab of u.abilities){ const k = ab.name + '|' + ab.text + '|' + (naReason(ab) ? 'na' : ''); if(!groups.has(k)) groups.set(k, { ab, units:[] }); groups.get(k).units.push(u); }
  // an ability a listed one selects (pickOptions) names its selector on its own line too, as "Riled up (War Cry)" does: "The Blood God’s
  // Favour (Wrathful Presence) · Angron"
  const selBy = new Map();
  for(const { ab, units:us } of groups.values()){ const e = ckStored(entry('a|' + ckHash(ab.name + '\n' + ab.text)), ab), pb = !naReason(ab) && perBattle(ab);
    if(e.pk && !pb && ckListed(e, pb)) for(const P of pickOptions(ab, us[0]).list) selBy.set(P, (selBy.has(P) ? selBy.get(P) + ', ' : '') + ab.name); }
  for(const { ab, units:us } of groups.values()){
    const e = ckStored(entry('a|' + ckHash(ab.name + '\n' + ab.text)), ab), na = naReason(ab), pb = !na && perBattle(ab), key = abilityKey(ab), trig = ckListed(e, pb);
    const dn = ab.name + (selBy.has(ab) ? ' (' + selBy.get(ab) + ')' : '');
    const aid = 'a:' + ab.name + '|' + ckHash(ab.text) + (na ? '|na' : '');   // (a copy the list cannot use: its own boxes, as its own line)
    if(!trig && !(e.o || []).some(o => o.s)) continue;   // on its datasheet
    const line = linkTo('ability', key, dn) + from(unitNamesX(us, ab) + given(ab.name)) + naTag(na);
    // a box for each copy when a unit on the line is ×N (each copy uses it on its own: ckTick)
    const n = us.some(u => u.copies > 1) ? us.reduce((t, u) => t + (u.copies || 1), 0) : 1;
    if(!trig){ items.push({ id:aid, kind:'abs', e, line, what:ab.name, once:null, n }); continue; }   // listed only through its options: itself, once
    // once per battle: the Overview's boxes, the army's or one set per unit (each copy of a ×N unit)
    const once = !pb ? null : pb.army ? [[abilityTicks(ab, us[0]), line + ' <span class="tg once">per army</span>']]
      : us.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) => [ticks(copyKey(ab, u, i), pb.n, '', ab.name + (u.copies > 1 ? ', Unit ' + (i + 1) : '')),
        linkTo('ability', key, dn) + ' · ' + linkTo('unit', u.id, unitLabel(u)) + (u.copies > 1 ? ' <span class="from">· Unit ' + (i + 1) + '</span>' : '')]));
    items.push({ id:aid, kind:'abs', e, line, what:ab.name, once, n });
    if(!pb){ forced(e.f, ab.name, 'abs', aid);
      // the ability it selects (pickOptions: Wrathful Presence's, Icon of War from Rod of the War Forge): Active now where that ability is
      // used, within the duration its words give (pk), unless it is listed itself or its own trigger is a unit activation (a)
      if(e.pk) for(const P of pickOptions(ab, us[0]).list){ const eP = ckStored(entry('a|' + ckHash(P.name + '\n' + P.text)), P);
        if(eP.a || ckListed(eP, !naReason(P) && perBattle(P))) continue;
        // where it is used: its own use, or, for one made only of options, theirs when every one is read, within the selector's duration;
        // not read (Icon of War: The Fires of Mars is x): the selector's whole duration (pk), as an option of which nothing is read takes
        // its rule's (ckOption); the selector's duration not read (pk.x): When unclear
        const oU = !eP.u && (eP.o || []).length && eP.o.every(o => o.u) ? eP.o.map(o => o.u) : null, use = eP.u || (oU && ckUnion(oU));
        items.push({ id:'pk:' + aid + ':' + P.name, kind:'abs', e:e.pk.x ? { x:1 } : use ? ckWithin(use, e.pk.u) : { u:e.pk.u }, what:P.name,
          line:linkTo('ability', abilityKey(P), P.name + ' (' + ab.name + ')') + from(unitNamesX(us, ab)), once:null, n }); } }
    for(const o of e.o || []) if(ckOptListed(o, true)){ items.push({ id:'ao' + aid.slice(1) + ':' + o.n, kind:'abs', e:ckOption(o, e), what:o.n,
      line:linkTo('ability', key, o.n) + from('option of ' + esc(ab.name) + ' · ' + unitNamesX(us, ab)) + naTag(na), once:null, n }); forced(o.f, o.n, 'abs', 'ao' + aid.slice(1) + ':' + o.n); }
  }
  // each to its sections: a moment, or a phase in one player's turn ("command|your")
  const sec = {}, put = (s, g, html) => { const x = sec[s] = sec[s] || {}; (x[g] = x[g] || []).push(html); };
  const turns = t => t === 'either' ? ['your', 'opp'] : [t];
  for(const it of items){
    const e = it.e;
    if((e.x || !(e.t || e.u || e.at || e.none || e.ends)) && !(it.once && e.via && (e.via.t || e.via.at))){ put('unclear', it.kind, tl(ckTick('unclear|' + it.id, it.what, it.n), it.line)); continue; }
    if(e.none){ put('none', it.kind, tl(ckTick('none|' + it.id, it.what, it.n), it.line)); continue; }
    if(e.ends && !e.t && !e.at && !e.u){ for(const s of e.ends) put(s, 'todo', tl(ckTick(s + '|' + it.id, it.what, it.n), it.line)); continue; }
    const secs = x => [...new Set(ckAt(x.at).concat(Object.entries(ckMap(x.t)).flatMap(([p, t]) => turns(t).map(w => p + '|' + w)), x.ae ? [x.ae] : []))];
    const trig = secs(e), act = Object.entries(ckMap(e.u)).flatMap(([p, t]) => turns(t).map(w => p + '|' + w)).filter(s => !trig.includes(s));
    // once per battle: where it is used from (its trigger, its rule's, or else where its effect is used)
    if(it.once){ const via = e.via ? secs(e.via) : []; for(const s of trig.length ? trig : via.length ? via : act) for(const [b, l] of it.once) put(s, 'once', tl(b, l)); continue; }
    for(const s of trig) put(s, 'todo', tl(ckTick(s + '|' + it.id, it.what, it.n), it.line));
    for(const s of act) put(s, 'active', tl(ckTick(s + '|' + it.id, it.what, it.n), it.line));
  }
  const GROUPS = [['todo', 'To do now', 'to do'], ['active', 'Active now', 'active'], ['once', 'Once per battle', 'once per battle'], ['rules', 'Rules', 'rules'], ['abs', 'Abilities', 'abilities']];
  const phaseSecs = PHASES.flatMap(([p]) => [p + '|your', p + '|opp']);
  // the moments in the order of the game: before the phases, after Fight · Their turn (the end of your turn, of your opponent's, of the round)
  const order = ['Start of the first battle round', 'Start of the battle round'].filter(s => sec[s]).concat(phaseSecs, ['End of your turn', 'End of your opponent’s turn', 'End of the battle round', 'unclear', 'none'].filter(s => sec[s]));
  const title = s => s === 'unclear' ? 'When unclear' : s === 'none' ? 'No phase' : s.includes('|') ? PHASE_NAME[s.split('|')[0]] + ' · ' + TURN_NAME[s.split('|')[1]] : s;
  // each section a fold, as the Overview's rules: its name, and on the line under it how many lines each part has
  const fold = s => { const g = sec[s] || {}, parts = GROUPS.filter(([k]) => g[k]), k = 'ck|' + a.id + '|' + s;
    return '<details class="ab rr" data-ckfold="' + esc(k) + '"' + (openStrats.has(k) ? ' open' : '') + '><summary><span class="an"><b>' + esc(title(s)) + '</b><span class="rs">' +
      (parts.length ? metaLine(...parts.map(([x, , w]) => g[x].length + ' ' + w)) : 'nothing') + '</span></span>' + chev + '</summary><div class="body">' +
      (parts.length ? parts.map(([x, l]) => '<div class="ckg"><p class="qh">' + l + '</p>' + g[x].join('') + '</div>').join('') : '<p class="note">Nothing in this list.</p>') + '</div></details>'; };
  return '<div class="ckl"><div class="sec-h"><h2>Phase by phase</h2><button class="textbtn" data-ckreset>Reset</button></div><div class="abl">' + order.map(fold).join('') + '</div>' +
    '<p class="note">Listed: what you must remember when the game reaches a moment: a rule or ability whose own words name the start or end of a battle round, turn or phase, a Command phase, or another phase with a choice (To do now there; a rule listed only through such options is listed once, as the rule), and once-per-battle uses (Once per battle, their box only). Active now: what the others put in force, where it is used and for as long as their words say: their options, the ability they select, and a rule they name in bold as a state units are in (Riled up), unless its own trigger is a unit activation. What activating a unit triggers (selected to shoot, fight or move; each time it attacks, is targeted or destroys) is on its datasheet. When unclear: listed, but no phase can be read from its words. No phase: listed, with no phase. Each line opens the full text. Stratagems are on the Stratagems tab. Reset clears the boxes here, not the once-per-battle ones.</p></div>';
}
